import{_ as s,o as a,c as n}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 12 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"12","title":"Page 12 | Home","prev":"/page/11/","next":"/page/13/","posts":[{"title":"数据库查询的N+1问题","url":"/posts/2021-02-20-sql-n-1/","date":"2021-02-20 13:44","tags":["database"],"html":"<p>在工作中有时也会涉及到后端开发，后端开发的性能优化多是查询优化。类似前端 DOM 操作很消耗性能，后端开发数据库查询次数也会相当消耗性能。我们在开发中应该尽量减少 SQL 查询次数，避免 N+1 问题来提升性能。接下来就来介绍数据库查询的 N+1 问题。</p>\\n<h2 id=\\"sql-n-1\\" tabindex=\\"-1\\">SQL N+1 <a class=\\"header-anchor\\" href=\\"#sql-n-1\\" aria-label=\\"Permalink to &quot;SQL N+1&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>举一个简单的例子，数据库中有一张 <code>cars</code> 表存储汽车的相关信息，还有一张 <code>wheels</code> 表存储汽车的轮胎信息。</p>\\n<p>查询汽车的语句是：</p>\\n<div class=\\"language-sql line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">sql</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">SELECT</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#D73A49\\"> FROM</span><span style=\\"color:#24292E\\"> cars;</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>查询每个汽车的轮子的语句是：</p>\\n<div class=\\"language-sql line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">sql</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">SELECT</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#D73A49\\"> FROM</span><span style=\\"color:#24292E\\"> wheels </span><span style=\\"color:#D73A49\\">WHERE</span><span style=\\"color:#24292E\\"> car_id </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> \${car_id};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>这里的 N 就是汽车的数量，如果需要知道每个汽车的轮胎信息那就正好需要查询 <code>N+1</code> 次。</p>\\n<h2 id=\\"解决-n-1\\" tabindex=\\"-1\\">解决 N+1 <a class=\\"header-anchor\\" href=\\"#解决-n-1\\" aria-label=\\"Permalink to &quot;解决 N+1&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如果汽车和轮胎是一对一的关系可以通过使用 <code>join</code> 语句来减少数据库查询次数。把查询降为 1 次。修正之后的查询语句是：</p>\\n<div class=\\"language-sql line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">sql</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">SELECT</span><span style=\\"color:#24292E\\"> cars.</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#24292E\\">, wheels.</span><span style=\\"color:#D73A49\\">*</span><span style=\\"color:#D73A49\\"> FROM</span><span style=\\"color:#24292E\\"> cars </span><span style=\\"color:#D73A49\\">INNER JOIN</span><span style=\\"color:#24292E\\"> wheels </span><span style=\\"color:#D73A49\\">ON</span><span style=\\"color:#005CC5\\"> wheels</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">car_id</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#005CC5\\"> cars</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">id</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>如果汽车和轮胎是一对多的关系可以通过使用：</p>\\n<div class=\\"language-sql line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">sql</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">SELECT</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#D73A49\\"> FROM</span><span style=\\"color:#24292E\\"> cars;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">SELECT</span><span style=\\"color:#D73A49\\"> *</span><span style=\\"color:#D73A49\\"> FROM</span><span style=\\"color:#24292E\\"> wheels </span><span style=\\"color:#D73A49\\">WHERE</span><span style=\\"color:#005CC5\\"> wheels</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#005CC5\\">car_id</span><span style=\\"color:#D73A49\\"> IN</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#005CC5\\">1</span><span style=\\"color:#24292E\\">,</span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">,</span><span style=\\"color:#005CC5\\">3</span><span style=\\"color:#24292E\\">)</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>一次性查询所有需要的轮胎把查询降为两次。</p>\\n<h2 id=\\"现有框架解决方案\\" tabindex=\\"-1\\">现有框架解决方案 <a class=\\"header-anchor\\" href=\\"#现有框架解决方案\\" aria-label=\\"Permalink to &quot;现有框架解决方案&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"django\\" tabindex=\\"-1\\">Django <a class=\\"header-anchor\\" href=\\"#django\\" aria-label=\\"Permalink to &quot;Django&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>Django 可以使用<a href=\\"https://docs.djangoproject.com/en/3.1/ref/models/querysets/#select-related\\" target=\\"_blank\\" rel=\\"noreferrer\\">select-related</a> 和 <a href=\\"https://docs.djangoproject.com/en/3.1/ref/models/querysets/#prefetch-related\\" target=\\"_blank\\" rel=\\"noreferrer\\">prefetch-related</a>来解决这个问题。</p>\\n<p><code>select-related</code> 主要用于一对一的关系，而 <code>prefetch-related</code> 主要用于多对多或者多对一的关系。</p>\\n<h3 id=\\"ruby-on-rails\\" tabindex=\\"-1\\">Ruby on Rails <a class=\\"header-anchor\\" href=\\"#ruby-on-rails\\" aria-label=\\"Permalink to &quot;Ruby on Rails&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>使用 <a href=\\"https://api.rubyonrails.org/v6.1.3/classes/ActiveRecord/QueryMethods.html#method-i-includes\\" target=\\"_blank\\" rel=\\"noreferrer\\">includes</a> 来解决 N+1 问题。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>后端开发需要时刻注意 N+1 问题， 在开发模式下，日志会输出 SQL 查询语句，需要多加注意。也可以使用一些工具来检测这个问题。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://stackoverflow.com/questions/97197/what-is-the-n1-selects-problem-in-orm-object-relational-mapping\\" target=\\"_blank\\" rel=\\"noreferrer\\">What is the “N+1 selects problem” in ORM</a></p>\\n<p><a href=\\"https://guides.rubyonrails.org/active_record_querying.html\\" target=\\"_blank\\" rel=\\"noreferrer\\">Active Record Query Interface</a></p>\\n"},{"title":"提高网页的易读性","url":"/posts/2021-02-06-web-accessibility/","date":"2021-02-06 11:04","tags":["accessibility"],"html":"<p>正常人可以通过鼠标和键盘来操作浏览器，使用滚轮来滚动网页，使用鼠标左键和右键来执行操作，使用键盘输入内容。但是对于残疾人来说可能就不是这样的了，如果一个人身体行动不便只能通过键盘敲击来操作电脑，无法使用鼠标的情况下，如果网页不支持键盘 <code>Tab</code> 键来切换各种点击按钮，那就会给残疾人的使用带来困难。如果视力不好的人只能借助屏幕阅读器来查看网页，如果按钮或者图片没有合适的标签信息，那就无法通过屏幕阅读器来听到这个按钮或者图片的含义。我们不仅要考虑正常人如何查看网页，也需要顾及到特殊人群的需求，这样才能让每个人都享受到互联网带来的便利。</p>\\n<h2 id=\\"focus\\" tabindex=\\"-1\\">focus <a class=\\"header-anchor\\" href=\\"#focus\\" aria-label=\\"Permalink to &quot;focus&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>focus 状态对于网页易读性非常重要，foucs 决定了键盘事件的去向。但是我们在项目开发的时候经常会给 <code>button</code> 添加鼠标的 <code>hover</code> 状态，却忘记了添加 <code>focus</code> 状态。添加 <code>hover</code> 状态的 CSS 时，记得同时添加 <code>focus</code> 状态的 CSS。同时，浏览器会有默认的 <code>focus</code> 样式， Chrome 下是使用 <code>outline</code> 属性添加高亮的蓝色边框，记得不要轻易覆盖这个属性为 <code>none</code>。\\n但是并不是所有的 HTML 元素都是可以 <code>focus</code> 的，下面是查找可以 <code>focus</code> 的元素的方法。</p>\\n<div class=\\"language-ts line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">ts</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> candidateSelectors</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> [</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'input:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'select:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'textarea:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'a[href]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'area[href]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'button:not([disabled])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  '[tabindex=\\"0\\"]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'audio[controls]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'video[controls]'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  '[contenteditable]:not([contenteditable=\\"false\\"])'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#032F62\\">  'details>summary'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">];</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> candidateSelector</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> candidateSelectors.</span><span style=\\"color:#6F42C1\\">join</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#032F62\\">','</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">type</span><span style=\\"color:#6F42C1\\"> Option</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#E36209\\">  shouldIgnoreVisibility</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#005CC5\\"> defaultOption</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Option</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  shouldIgnoreVisibility: </span><span style=\\"color:#005CC5\\">false</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">)</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#005CC5\\"> boolean</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#D73A49\\">!</span><span style=\\"color:#24292E\\">node) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).display </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'none'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#6F42C1\\"> isDisplayNone</span><span style=\\"color:#24292E\\">(node.parentElement);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">function</span><span style=\\"color:#6F42C1\\"> isHidden</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">node</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> Element</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">getComputedStyle</span><span style=\\"color:#24292E\\">(node).visibility </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'hidden'</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (</span><span style=\\"color:#6F42C1\\">isDisplayNone</span><span style=\\"color:#24292E\\">(node)) </span><span style=\\"color:#D73A49\\">return</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">export</span><span style=\\"color:#D73A49\\"> function</span><span style=\\"color:#6F42C1\\"> tabbable</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">el</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> HTMLElement</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">option</span><span style=\\"color:#D73A49\\">?:</span><span style=\\"color:#6F42C1\\"> Partial</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">Option</span><span style=\\"color:#24292E\\">>) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> mergedOption</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ...</span><span style=\\"color:#24292E\\">defaultOption,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    ...</span><span style=\\"color:#24292E\\">option</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> candidates</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#24292E\\"> Array.</span><span style=\\"color:#6F42C1\\">from</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    el.</span><span style=\\"color:#6F42C1\\">querySelectorAll</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLElement</span><span style=\\"color:#24292E\\">>(candidateSelector)</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  if</span><span style=\\"color:#24292E\\"> (mergedOption.shouldIgnoreVisibility) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> candidates;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> candidates.</span><span style=\\"color:#6F42C1\\">filter</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">candidate</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#D73A49\\"> !</span><span style=\\"color:#6F42C1\\">isHidden</span><span style=\\"color:#24292E\\">(candidate));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br></div></div><h2 id=\\"dom-order\\" tabindex=\\"-1\\">DOM Order <a class=\\"header-anchor\\" href=\\"#dom-order\\" aria-label=\\"Permalink to &quot;DOM Order&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>当你使用键盘的 <code>Tab</code> 来选择下一个按钮的时候，是如何决定顺序的呢？ 答案是根据 DOM 的顺序而不是界面上 UI 的顺序，你可以使用 CSS 来调整 UI 顺序，但是 <code>Tab</code> 顺序不会改变。\\n针对隐藏的元素， <code>Tab</code> 键也不会触发这个元素的 <code>focus</code>，隐藏的元素 CSS 属性可能含有 <code>display: none</code> 或者 <code>visibility: hidden</code>。</p>\\n<h2 id=\\"tabindex\\" tabindex=\\"-1\\">tabindex <a class=\\"header-anchor\\" href=\\"#tabindex\\" aria-label=\\"Permalink to &quot;tabindex&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>对于 <code>button</code> 和 <code>a</code> 元素，当然是可以 <code>focus</code> 的，但是针对类似 <code>div</code> 这样的元素，如何让它可以 <code>focus</code> 呢？ 答案是添加 <code>tabindex</code> 属性。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">custom-button</span><span style=\\"color:#6F42C1\\"> tabindex</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"0\\"</span><span style=\\"color:#24292E\\">>Press Tab to Focus Me!&#x3C;/</span><span style=\\"color:#22863A\\">custom-button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>通过添加 <code>tabindex=&quot;0&quot;</code> 可以使这个元素被 <code>focus</code>。那么如何使一个元素不被 <code>focus</code>呢？</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> id</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"foo\\"</span><span style=\\"color:#6F42C1\\"> tabindex</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"-1\\"</span><span style=\\"color:#24292E\\">>I'm not keyboard focusable&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> onclick</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"</span><span style=\\"color:#24292E\\">foo</span><span style=\\"color:#032F62\\">.</span><span style=\\"color:#6F42C1\\">focus</span><span style=\\"color:#032F62\\">();\\"</span><span style=\\"color:#24292E\\">>Focus my sibling&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br></div></div><p>使用 <code>tabindex=&quot;-1&quot;</code> 可以确保这个元素不会使用键盘 <code>focus</code>，但是鼠标没有影响。\\n<code>tabindex</code> 当然可以设置大于 0 的值，但我们不推荐这么做，因为默认元素的 <code>tabindex</code> 都是 0，所以大于 0 的元素最后才会触发 <code>focus</code>。\\n现在的网页开发，我们都会自己手动实现 <code>select</code> 或者 <code>dropdown</code> 元素，但由于这些不是默认的 HTML 元素，所以需要自己实现键盘的 <code>Tab</code> 键或者方向键的触发。</p>\\n<h2 id=\\"modals-and-keyboard-traps\\" tabindex=\\"-1\\">Modals and keyboard traps <a class=\\"header-anchor\\" href=\\"#modals-and-keyboard-traps\\" aria-label=\\"Permalink to &quot;Modals and keyboard traps&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>网页开发中经常会出现弹窗，在有弹窗的情况下我们是不能选中背景中的元素的，所以我们需要手动处理 <code>Tab</code> 键保证只有 <code>Modal</code> 里的元素可以被 <code>focus</code>。并且在关闭 <code>Modal</code> 的时候 <code>focus</code> 回原来的元素。</p>\\n<h2 id=\\"semantics-and-aria\\" tabindex=\\"-1\\">Semantics and ARIA <a class=\\"header-anchor\\" href=\\"#semantics-and-aria\\" aria-label=\\"Permalink to &quot;Semantics and ARIA&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们经常使用 HTML 元素来模拟一些功能，例如使用 <code>button</code> 按钮来模拟菜单功能。这时候我们需要为 <code>button</code> 添加 <code>aria-label</code> 属性方便屏幕阅读器理解这个按钮代表的含义。</p>\\n<div class=\\"language-html line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">html</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#6F42C1\\"> aria-label</span><span style=\\"color:#24292E\\">=</span><span style=\\"color:#032F62\\">\\"menu\\"</span><span style=\\"color:#24292E\\">>&#x3C;/</span><span style=\\"color:#22863A\\">button</span><span style=\\"color:#24292E\\">></span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>当然啦，这种类似的属性还有很多，例如 <code>role</code> 属性来描述这个元素的定位。</p>\\n<h2 id=\\"accessibility-review\\" tabindex=\\"-1\\">Accessibility Review <a class=\\"header-anchor\\" href=\\"#accessibility-review\\" aria-label=\\"Permalink to &quot;Accessibility Review&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>如何检查自己网页的易读性呢，现在也有现成的网页工具和可以集成的 CI 工具。我们可以使用 Chrome 浏览器自带的 <code>Lighthouse</code> 来检查自己网页的易读性。如果想集成 CI 的话，可以试试<a href=\\"https://github.com/dequelabs/axe-core\\" target=\\"_blank\\" rel=\\"noreferrer\\">axe-core</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>提高网页的易读性，不仅可以使用键盘提高操作网页的便利性，也可以照顾特殊人群的使用，何乐而不为呢。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/udacity/ud891/tree/gh-pages/lesson2-focus/07-modals-and-keyboard-traps/solution\\" target=\\"_blank\\" rel=\\"noreferrer\\">Modals and keyboard traps sample code</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/accessibility\\" target=\\"_blank\\" rel=\\"noreferrer\\">Accessibility</a></p>\\n<p><a href=\\"https://www.w3.org/TR/wai-aria-practices-1.1/\\" target=\\"_blank\\" rel=\\"noreferrer\\">WAI-ARIA Authoring Practices</a></p>\\n"},{"title":"JavaScript的加载优化","url":"/posts/2021-01-23-javascript-performance/","date":"2021-01-23 16:11","tags":["performance"],"html":"<p>前端开发中，JavaScript 变得越来越重要，页面载入中，JavaScript 占的比重也更高。不同与别的静态资源，例如图片和 SVG 图标。浏览器在解析 JavaScript 时花的时间要多得多。所以优化 JavaScript 也就变得非常重要。</p>\\n<h2 id=\\"减少-javascript-的网络传输开销\\" tabindex=\\"-1\\">减少 JavaScript 的网络传输开销 <a class=\\"header-anchor\\" href=\\"#减少-javascript-的网络传输开销\\" aria-label=\\"Permalink to &quot;减少 JavaScript 的网络传输开销&quot;\\">&ZeroWidthSpace;</a></h2>\\n<h3 id=\\"only-sending-the-code-a-user-needs\\" tabindex=\\"-1\\">Only sending the code a user needs. <a class=\\"header-anchor\\" href=\\"#only-sending-the-code-a-user-needs\\" aria-label=\\"Permalink to &quot;Only sending the code a user needs.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>一方面，只加载当前页面需要的 JavaScript 文件，可以使用 webpack 的<a href=\\"https://webpack.js.org/guides/code-splitting/\\" target=\\"_blank\\" rel=\\"noreferrer\\">code-splitting</a>来解决。另一方面，懒加载一些不是必须的 JavaScript 文件。</p>\\n<h3 id=\\"minification\\" tabindex=\\"-1\\">Minification <a class=\\"header-anchor\\" href=\\"#minification\\" aria-label=\\"Permalink to &quot;Minification&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>使用<a href=\\"https://github.com/terser/terser\\" target=\\"_blank\\" rel=\\"noreferrer\\">terser</a>来压缩 JavaScript 代码。</p>\\n<h3 id=\\"compression\\" tabindex=\\"-1\\">Compression <a class=\\"header-anchor\\" href=\\"#compression\\" aria-label=\\"Permalink to &quot;Compression&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>服务器开启 GZIP 来减少传输的文件大小。</p>\\n<h3 id=\\"removing-unused-code\\" tabindex=\\"-1\\">Removing unused code. <a class=\\"header-anchor\\" href=\\"#removing-unused-code\\" aria-label=\\"Permalink to &quot;Removing unused code.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>针对一些第三方 JavaScript 库，可以使用<a href=\\"https://webpack.js.org/guides/tree-shaking/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Tree Shaking</a>来移除不需要的代码。</p>\\n<h3 id=\\"caching-code-to-minimize-network-trips\\" tabindex=\\"-1\\">Caching code to minimize network trips. <a class=\\"header-anchor\\" href=\\"#caching-code-to-minimize-network-trips\\" aria-label=\\"Permalink to &quot;Caching code to minimize network trips.&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>使用 <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/ETag\\" target=\\"_blank\\" rel=\\"noreferrer\\">ETag</a>, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Last-Modified\\" target=\\"_blank\\" rel=\\"noreferrer\\">Last-Modified</a>, <a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Headers/Cache-Control\\" target=\\"_blank\\" rel=\\"noreferrer\\">Cache-Control</a> 三个配合有效的缓存 JavaScript 文件。</p>\\n<h2 id=\\"优化-javascript-下载和执行\\" tabindex=\\"-1\\">优化 JavaScript 下载和执行 <a class=\\"header-anchor\\" href=\\"#优化-javascript-下载和执行\\" aria-label=\\"Permalink to &quot;优化 JavaScript 下载和执行&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>我们可以通过使用 <code>async</code> 或者 <code>defer</code> 来优化 JavaScript 的下载和执行，两个关键字的具体作用看下图：</p>\\n<p><img src=\\"/assets/js_async_defer.png\\" alt=\\"js async defer\\"></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>JavaScript 的优化并没有银弹，要根据具体项目的实际情况来处理。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://developer.mozilla.org/en-US/docs/Web/HTTP/Caching\\" target=\\"_blank\\" rel=\\"noreferrer\\">HTTP caching</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/javascript-startup-optimization?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">JavaScript Start-up Optimization</a></p>\\n<p><a href=\\"https://developers.google.com/web/fundamentals/performance/optimizing-content-efficiency/loading-third-party-javascript?hl=en\\" target=\\"_blank\\" rel=\\"noreferrer\\">Loading Third-Party JavaScript</a></p>\\n"}]},"relativePath":"page/12/index.md","filePath":"page/[page].md"}`),e={name:"page/12/index.md"};function l(o,p,r,t,c,i){return a(),n("div")}const y=s(e,[["render",l]]);export{b as __pageData,y as default};
